∀ (e : CellularAutomatas.SimFromΛ),
  e.C =
    { Q := e.Q, alphabetQ := CellularAutomatas.instAlphabetOfDecidableEqOfFintypeOfInhabited e.Q,
      δ := fun qa qb qc =>
        have next_q_ctl := e.C_ctl.δ qa.state qb.state qc.state;
        have trigger := e.C_ctl.project next_q_ctl;
        match trigger with
        | some s => { state := next_q_ctl, counter := 0, sim := some (e.C_inr.embed s, e.C_inr.embed s) }
        | none =>
          match qb.sim with
          | some (new_b, old_b) =>
            if (qb.counter == 2) = true then
              have val_a := e.get_neighbor_val qa;
              have val_c := e.get_neighbor_val qc;
              have next_val := e.C_inr.δ val_a new_b val_c;
              { state := next_q_ctl, counter := 0, sim := some (next_val, new_b) }
            else { state := next_q_ctl, counter := qb.counter + 1, sim := some (new_b, old_b) }
          | none => { state := next_q_ctl, counter := 0, sim := none },
      embed := fun a => { state := e.C_ctl.embed a, counter := 0, sim := none },
      project := fun q =>
        if (q.counter == 0) = true then
          match q.sim with
          | some (new, snd) => some (e.C_inr.project new)
          | none => none
        else none }

∀ (e : CellularAutomatas.CompressToDiag),
  e.C =
    { Q := (Fin 4 → e.speedup.C.Q) ⨉ (Fin 4 → e.speedup.C.Q), alphabetQ := CellularAutomatas.ProductAlphabet,
      δ := fun a b c =>
        have aS := a.1;
        have bS := b.1;
        have cS := c.1;
        have newState :=
          e.speedup.C.δ (aS ⟨3, CellularAutomatas.CompressToDiag.C._proof_2⟩)
            (bS ⟨3, CellularAutomatas.CompressToDiag.C._proof_2⟩) (cS ⟨3, CellularAutomatas.CompressToDiag.C._proof_2⟩);
        have newSelf := fun j => if h : ↑j < 3 then bS ⟨↑j + 1, ⋯⟩ else newState;
        (newSelf, cS),
      embed := fun x =>
        have q := e.speedup.C.embed x;
        (fun x => q, fun x => q),
      project := fun s =>
        have self := s.1;
        have rightHist := s.2;
        have o0 := e.speedup.C.project (self ⟨0, CellularAutomatas.CompressToDiag.C._proof_5⟩);
        have o1 := e.speedup.C.project (self ⟨1, CellularAutomatas.CompressToDiag.C._proof_6⟩);
        have o2 := e.speedup.C.project (rightHist ⟨3, CellularAutomatas.CompressToDiag.C._proof_2⟩);
        have v0 := (e.speedup.g2 o0).2;
        have v1 := e.speedup.g1 o1;
        have v2 := (e.speedup.g2 o2).1;
        some fun j =>
          match j with
